const _ = require('lodash');
const constant = require('../lib/constant');

/**
 * list:
 * lindex key index
 * linsert key BEFORE|AFTER pivot value
 * llen key
 * lpop key
 * lpush key value [value ...]
 * lrange key start stop
 * lrem key count value
 * lset key index value
 * rpop key
 * rpush key value [value ...]
 */
module.exports = (common) => {
  const operations = {
    * lindex(key, index, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      const list = yield operations.lrange(key, 0, -1, forceMaster);
      if (list === undefined) {
        return undefined;
      }
      if (list === null || !_.isArray(list) || list.length === 0 || index > list.length - 1 || index < -list.length) {
        return null;
      }
      if (index < 0) {
        index = list.length + index;
      }
      return list[index];
    },

    * linsert(key, direction, pivot, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || (direction !== constant.DIRECTION.BEFORE && direction !== constant.DIRECTION.AFTER)) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value) || objVer.value.length === 0) {
          return 0;
        }
        let exists = false;
        const list = objVer.value;
        for (let i = 0; i < list.length; i++) {
          if (_.isEqual(list[i], pivot)) {
            exists = true;
            if (direction === constant.DIRECTION.BEFORE) {
              list.splice(i, 0, value);
            } else {
              list.splice(i + 1, 0, value);
            }
            break;
          }
        }
        if (!exists) {
          return -1;
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(objVer.value, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return list.length;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * llen(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      const list = yield operations.lrange(key, 0, -1, forceMaster);
      if (list === undefined) {
        return undefined;
      }
      /* istanbul ignore if */
      if (list === null || !_.isArray(list)) {
        return 0;
      }
      return list.length;
    },

    * lpop(key) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value)) {
          return null;
        } else if (objVer.value.length === 0) {
          return 0;
        }
        const list = objVer.value;
        const node = list.shift();
        const ret = yield common.setStringEx(key, common.toStringWithType(list, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return node;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * lpush(key, ...value) {
      const values = common.getFieldToArray(value);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || values === null) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let list;
        if (objVer === null || objVer.value === null) {
          list = [];
        } else {
          list = objVer.value;
        }
        list.unshift(...values);
        const ret = yield common.setStringEx(key, common.toStringWithType(list, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * lrange(key, start, stop, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || common.isNotStrOrEmpty(key)) {
        return [];
      }
      start = common.convertToInt(start);
      stop = common.convertToInt(stop);
      const list = yield common.getValue(key, constant.TYPE.LIST, forceMaster);
      if (list === undefined) {
        return undefined;
      }
      if (list === null) {
        return [];
      }
      if (stop === -1) {
        stop = undefined;
      } else if (stop < 0) {
        stop++;
      }
      return list.slice(start, stop);
    },

    * lrem(key, count, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return 0;
      }
      count = common.convertToInt(count);
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value) || objVer.value.length === 0) {
          return 0;
        }
        const list = objVer.value;

        let equal = 0;
        if (count >= 0) {
          for (let i = 0; i < list.length; i++) {
            if (_.isEqual(list[i], value)) {
              list.splice(i--, 1);
              if (++equal >= count && count !== 0) {
                break;
              }
            }
          }
        } else {
          for (let i = list.length - 1; i >= 0; i--) {
            if (_.isEqual(list[i], value)) {
              list.splice(i++, 1);
              if (++equal >= -count && count !== 0) {
                break;
              }
            }
          }
        }
        const ret = yield common.setStringEx(key, common.toStringWithType(list, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return equal;
        }
      }
      /* istanbul ignore next */
      return 0;
    },

    * lset(key, index, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      index = common.convertToInt(index);
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value) || objVer.value.length === 0 || index > objVer.value.length - 1) {
          return false;
        }
        objVer.value[index] = value;
        const ret = yield common.setStringEx(key, common.toStringWithType(objVer.value, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * rpop(key) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        if (objVer === null || objVer.value === null || !_.isArray(objVer.value)) {
          return null;
        } else if (objVer.value.length === 0) {
          return 0;
        }
        const list = objVer.value;
        const node = list.pop();
        const ret = yield common.setStringEx(key, common.toStringWithType(list, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return node;
        }
      }
      /* istanbul ignore next */
      return false;
    },

    * rpush(key, ...value) {
      value = common.getFieldToArray(value);
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      for (let i = 0; i < common.retry; i++) {
        const objVer = yield common.getValueWithVer(key, constant.TYPE.LIST, constant.CONSTANT.FORCEMASTER);
        if (objVer === undefined) {
          return undefined;
        }
        let list;
        if (objVer === null || objVer.value === null) {
          list = [];
        } else {
          list = objVer.value;
        }
        list.push(...value);
        const ret = yield common.setStringEx(key, common.toStringWithType(list, constant.TYPE.LIST), objVer.ver);
        if (ret === undefined) {
          return undefined;
        }
        if (ret) {
          return true;
        }
      }
      /* istanbul ignore next */
      return false;
    },
  };
  return operations;
};
